<template><section class="disclosures"><h3>Clinical privacy and guardian access</h3><p>Clinical permissions are separate from payment responsibility.</p><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><article v-for="g in grants" :key="`${g.clientId}-${g.guardianUserId}`"><strong>{{ g.clientName }}<span v-if="g.guardianName"> · {{ g.guardianName }}</span></strong><p>{{ g.level === 'payer_only' ? 'No clinical record access' : g.level.replaceAll('_',' ') }}<span v-if="g.reviewRequired"> · Care-team review needed</span></p><p v-if="g.scopes.length">Permitted: {{ g.scopes.map(s => s.replaceAll('_',' ')).join(', ') }}</p><p v-if="g.reviewDueDate">Next review: {{ new Date(g.reviewDueDate).toLocaleDateString() }}</p><details v-if="g.canRequestRestriction"><summary>Restrict this guardian’s clinical access</summary><p>This immediately hides clinical information from this guardian while the care team reviews your request. Their payment responsibility stays in place.</p><fieldset><legend>Information to restrict</legend><label v-for="scope in g.scopes" :key="scope"><input type="checkbox" :value="scope" v-model="restrictions[`${g.clientId}-${g.guardianUserId}`]" />{{ scope.replaceAll('_',' ') }}</label></fieldset><label>Reason (optional)<textarea v-model="reasons[`${g.clientId}-${g.guardianUserId}`]" rows="3" /></label><button :disabled="busy" @click="restrict(g)">Request restriction</button></details></article></section></template>
<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';const props=defineProps({agencyId:[Number,String]});const grants=ref([]),error=ref(''),message=ref(''),busy=ref(false),reasons=ref({}),restrictions=ref({});let sequence=0;
async function load(){const seq=++sequence;grants.value=[];if(!props.agencyId)return;try{const result=await api.get('/family-billing/clinical-access',{params:{agencyId:props.agencyId}});if(seq===sequence){grants.value=result.data.grants;for(const g of grants.value)restrictions.value[`${g.clientId}-${g.guardianUserId}`]=[...g.scopes];}}catch{if(seq===sequence)error.value='Clinical access details could not be loaded.';}}
async function restrict(g){busy.value=true;error.value='';try{await api.post(`/family-billing/clinical-access/${g.clientId}/${g.guardianUserId}/restrict`,{agencyId:props.agencyId,reason:reasons.value[`${g.clientId}-${g.guardianUserId}`],scopes:restrictions.value[`${g.clientId}-${g.guardianUserId}`]});message.value='Clinical access is restricted pending care-team review.';await load();}catch(e){error.value=e.response?.data?.error?.message||'Your request could not be saved.';}finally{busy.value=false;}}
watch(()=>props.agencyId,load,{immediate:true});
</script>
<style scoped>.disclosures{margin-top:30px}.disclosures article{padding:20px;margin:12px 0;border:1px solid #d6e1ed;border-radius:10px;background:white}.disclosures p{line-height:1.5}.disclosures textarea{display:block;width:100%;box-sizing:border-box;margin:12px 0;padding:10px}.disclosures button{padding:10px 16px;border:1px solid #9bafc4;border-radius:7px;background:#f0f5fb}.disclosures [role=alert]{color:#a91d1d}</style>
